            if after_op1 >= k_val:
                valA = after_op1 - k_val
                options.append((1, 1, valA))
            # PathB: Op2 then Op1 (if possible)
            if x >= k_val:
                after_op2 = x - k_val
                valB = (after_op2 + 1) // 2
