    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        cnt = [0] * 32
        ans = n + 1
        s = i = 0
        for j, x in enumerate(nums):
            s += x
            for h in range(32):
                if x >> h & 1:
                    cnt[h] = [cnt[h] + 1]
            while s >= k and i <= j:
