class Solution:
    def maxDistinctElements(self, nums: List[int], k: int) -> int:
        nums.sort()
        ans = 0
        pre = -inf
        for x in nums:
            cur = max(x + k, min(x - k, pre + 1))
            if cur > pre:
                ans += 1
                pre = cur + 1
        return ans

